CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "MaterialTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 6),
        "Name" character varying(100) NOT NULL,
        "DefectRate" numeric(10,6) NOT NULL,
        CONSTRAINT "PK_MaterialTypes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "PartnerTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 5),
        "Name" character varying(30) NOT NULL,
        CONSTRAINT "PK_PartnerTypes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "ProductTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 5),
        "Name" character varying(100) NOT NULL,
        "Coefficient" numeric(10,4) NOT NULL,
        CONSTRAINT "PK_ProductTypes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "Partners" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 6),
        "PartnerTypeId" integer NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Director" character varying(200) NOT NULL,
        "Email" character varying(254) NOT NULL,
        "Phone" character varying(30) NOT NULL,
        "Address" character varying(300) NOT NULL,
        "TaxNumber" character varying(12),
        "Rating" integer NOT NULL,
        CONSTRAINT "PK_Partners" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Partners_PartnerTypes_PartnerTypeId" FOREIGN KEY ("PartnerTypeId") REFERENCES "PartnerTypes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "Products" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 6),
        "ProductTypeId" integer NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Article" character varying(30) NOT NULL,
        "MinimumPrice" numeric(12,2) NOT NULL,
        CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Products_ProductTypes_ProductTypeId" FOREIGN KEY ("ProductTypeId") REFERENCES "ProductTypes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    CREATE TABLE "Sales" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 17),
        "PartnerId" integer NOT NULL,
        "ProductId" integer NOT NULL,
        "Quantity" integer NOT NULL,
        "SaleDate" date NOT NULL,
        CONSTRAINT "PK_Sales" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Sales_Partners_PartnerId" FOREIGN KEY ("PartnerId") REFERENCES "Partners" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Sales_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

