DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261116190648_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"MaterialTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "MaterialTypes") + 1,
            nextval(pg_get_serial_sequence('"MaterialTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"PartnerTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "PartnerTypes") + 1,
            nextval(pg_get_serial_sequence('"PartnerTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"ProductTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "ProductTypes") + 1,
            nextval(pg_get_serial_sequence('"ProductTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Partners"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Partners") + 1,
            nextval(pg_get_serial_sequence('"Partners"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Products"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Products") + 1,
            nextval(pg_get_serial_sequence('"Products"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Sales"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Sales") + 1,
            nextval(pg_get_serial_sequence('"Sales"', 'Id'))),
        false);
    END IF;
END $EF$;

